import type { PoolClient } from 'pg';
import { pool } from '../../database/src/pool.js';

/**
 * Reports whether a completed deletion request retains a tombstone for the customer. Every writer
 * of customer data must consult this before persisting, because retries, provider callbacks,
 * duplicate deliveries, and replayed events can arrive long after the request completed.
 */
export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM privacy.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

export async function isCustomerErasedInTransaction(
  client: PoolClient,
  merchantId: string,
  customerId: string,
): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM privacy.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

const IDENTIFYING_KEYS = new Set([
  'email', 'customerEmail', 'name', 'phone', 'externalReference', 'metadata', 'customerSnapshot',
  'billingName', 'billingAddress', 'brand', 'last4', 'providerToken', 'destination',
  'subject', 'body', 'value', 'line1', 'line2', 'city', 'region', 'postalCode', 'country',
]);

/**
 * Returns the payload with customer-identifying fields removed, keeping the identifiers and
 * monetary facts that make a retained record meaningful. Mirrors `privacy.redact_payload`.
 */
export function redactPayload(payload: Record<string, unknown>): Record<string, unknown> {
  const redacted = Object.fromEntries(
    Object.entries(payload).filter(([key]) => !IDENTIFYING_KEYS.has(key)),
  );
  return { ...redacted, customerErased: true };
}

