import { createHash, randomUUID } from 'node:crypto';
import { pool } from '../packages/database/src/pool.js';

const gateway = 'http://api-gateway:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const noScopeKey = `pf_local_test_noscope_${randomUUID()}`;

await pool.query(
  `INSERT INTO platform.api_keys(merchant_id,key_hash,label,scopes)
   VALUES('10000000-0000-4000-8000-000000000001',$1,'no privacy scope',ARRAY['customers:read','customers:write'])`,
  [createHash('sha256').update(noScopeKey).digest('hex')],
);

const customer = await (await fetch(`${gateway}/v1/customers`, {
  method: 'POST',
  headers: { authorization: `Bearer ${apiKey}`, 'content-type': 'application/json' },
  body: JSON.stringify({ externalReference: `edge-${randomUUID()}`, email: `edge-${randomUUID()}@example.test`, name: 'Edge' }),
})).json() as { id: string };

async function status(path: string, headers: Record<string, string>, key = apiKey): Promise<number> {
  return (await fetch(`${gateway}${path}`, { method: 'POST', headers: { authorization: `Bearer ${key}`, ...headers } })).status;
}

console.log('missing idempotency key ->', await status(`/v1/customers/${customer.id}/erasure-requests`, {}));
console.log('short idempotency key ->', await status(`/v1/customers/${customer.id}/erasure-requests`, { 'idempotency-key': 'short' }));
console.log('missing scope ->', await status(`/v1/customers/${customer.id}/erasure-requests`, { 'idempotency-key': randomUUID() }, noScopeKey));
console.log('no auth ->', (await fetch(`${gateway}/v1/erasure-requests/${randomUUID()}`)).status);
console.log('non-uuid request id ->', (await fetch(`${gateway}/v1/erasure-requests/not-a-uuid`, { headers: { authorization: `Bearer ${apiKey}` } })).status);
console.log('accepted ->', await status(`/v1/customers/${customer.id}/erasure-requests`, { 'idempotency-key': randomUUID() }));

await pool.query(`DELETE FROM platform.api_keys WHERE key_hash=$1`, [createHash('sha256').update(noScopeKey).digest('hex')]);
await pool.end();

