action.file_text:
import assert from 'node:assert/strict';
import { pool } from '../packages/database/src/pool.js';

const request = (await pool.query<{ id: string; merchant_id: string; customer_id: string }>(
  `SELECT id,merchant_id,customer_id FROM privacy.erasure_requests WHERE status='completed' ORDER BY created_at LIMIT 1`,
)).rows[0]!;

const before = (await pool.query<{ payments: string; invoices: string; postings: string }>(
  `SELECT
     (SELECT count(*) FROM payments.payment_intents WHERE customer_id=$1)::text payments,
     (SELECT count(*) FROM payments.invoices WHERE customer_id=$1)::text invoices,
     (SELECT count(*) FROM payments.ledger_postings)::text postings`,
  [request.customer_id],
)).rows[0]!;

// Simulate a worker that crashed mid-cleanup: an expired lease and no recorded step progress.
await pool.query(
  `UPDATE privacy.erasure_requests
   SET status='processing',completed_at=NULL,locked_by='crashed-worker',locked_at=now()-interval '5 minutes',
       lease_expires_at=now()-interval '4 minutes',last_error=NULL WHERE id=$1`,
  [request.id],
);

const recovered = await (async () => {
  for (let tries = 0; tries < 200; tries += 1) {
    const row = (await pool.query<{ status: string; last_error: string | null }>(
      `SELECT status,last_error FROM privacy.erasure_requests WHERE id=$1`, [request.id],
    )).rows[0]!;
    if (row.status === 'completed') return row;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error('the abandoned request never recovered');
})();
assert.equal(recovered.last_error, null, 'the recovered request reports an error');

const after = (await pool.query<{ payments: string; invoices: string; postings: string; tombstones: string }>(
  `SELECT
     (SELECT count(*) FROM payments.payment_intents WHERE customer_id=$1)::text payments,
     (SELECT count(*) FROM payments.invoices WHERE customer_id=$1)::text invoices,
     (SELECT count(*) FROM payments.ledger_postings)::text postings,
     (SELECT count(*) FROM privacy.erased_customers WHERE customer_id=$1)::text tombstones`,
  [request.customer_id],
)).rows[0]!;

assert.equal(after.payments, before.payments, 'resuming duplicated or destroyed payment records');
assert.equal(after.invoices, before.invoices, 'resuming duplicated or destroyed invoices');
assert.equal(after.postings, before.postings, 'resuming altered the append-only ledger');
assert.equal(Number(after.tombstones), 1, 'resuming duplicated the retained deletion record');

console.log(JSON.stringify({ status: 'resumed', requestId: request.id, retained: after }, null, 2));
await pool.end();

